ex.sol:
def run_agent(model, tools, task, max_steps=5):
    messages = [{'role': 'user', 'content': task}]
    for _ in range(max_steps):
        r = model(messages)
        if r['type'] == 'answer':
            return r['text']
        try:
            fn = tools[r['name']]
            content = str(fn(**r['input']))
        except Exception as e:
            content = f'Error: {e}'
        messages.append({'role': 'tool', 'id': r['id'], 'content': content})
    return 'Stopped: step limit'

def check_input(schema, data):
    T = {'string': str, 'integer': int, 'boolean': bool}
    props = schema.get('properties', {})
    errs = [f'missing {r}' for r in schema.get('required', []) if r not in data]
    for k, v in data.items():
        if k in props and type(v) is not T[props[k]['type']]:
            errs.append(f"{k} must be {props[k]['type']}")
    errs += [f'unexpected {k}' for k in data if k not in props]
    return errs

